            new QuoteId(entity.getQuoteId()),
            entity.getRevisionNumber(),
            entity.getVersion(),
            entity.getStatus(),
            rootLines,
            toDomainPrice(entity.getCurrentPriceResult())
        );
    }

    private QuoteLine toDomainLine(QuoteLineEntity entity) {
